import{z as B,x as A,o as r,c as d,q as E,j as s,D as l,d as e,s as i,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Elo 与 BT 评分","description":"","frontmatter":{"title":"Elo 与 BT 评分","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/elo-bt-rating.md","filePath":"llm/elo-bt-rating.md","lastUpdated":1791063341000}'),p={name:"llm/elo-bt-rating.md"};function m(T,a,_,h,c,u){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=E('<h1 id="elo-与-bt-评分" tabindex="-1">Elo 与 BT 评分 <a class="header-anchor" href="#elo-与-bt-评分" aria-label="Permalink to &quot;Elo 与 BT 评分&quot;">​</a></h1><div class="epigraph"><p>胜负场次是观测，评分是对潜在强度的估计。场次不够时，名次只是噪声的一种排列。</p><footer>—— Bradley-Terry 模型；Elo 作为在线近似；Arena 的用法见 [LMSYS](/llm/lmsys-arena)</footer></div><p><a href="/llm/pairwise-vs-pointwise">上一课</a>把成对选作排名仪器。把许多对战收成一个可排序的标量，常用 Elo 或 Bradley-Terry（BT）。主干 Arena 课已写产品形态；本课补评测进阶里的估计含义。缺口是把「榜上差 20 Elo」当成物理单位。后课风格控制默认：Elo 差可以来自长度，而不是来自强度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BT 假设 \\(P(i\\succ j)=\\sigma(s_i-s_j)\\)，用全体对战的似然估 \\(s\\)。Elo 是对同一差的在线更新，便于实时榜。二者都把传递性写进模型：若循环对战很多（A 胜 B、B 胜 C、C 胜 A），拟合残差会大，单一分数解释力下降。</p><p>场次不平衡：新模型对战少，置信区间宽。只报点估计会制造假名次。对战不是随机设计时（用户自选模型、提示偏代码），\\(s\\) 估计的是<strong>该流量下的强度</strong>，不是无条件能力。</p><p><span class="marginnote">把 Elo 与 MMLU 排进同一张「综合实力」表，是单位错误。一个来自成对口味，一个来自选择题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线 BT：构造对战表，极大似然或贝叶斯估计 \\(s\\)，用 bootstrap 或 Hessian 报区间。在线 Elo：公布 \\(K\\) 因子与初始分，否则不可复现。<span class="marginnote">K 因子是 Elo 每场对战的「步长」：赢一场加多少、输一场扣多少，都要乘上它。比如 \\(K=32\\) 时一场爆冷能让分数挪十几分，\\(K=8\\) 时只挪几分——K 太大榜单上蹿下跳，太小则新模型爬得很慢。公布 K 与初始分，别人才能复现你的榜。</span>过滤：过短对战、明显刷票、同一用户重复，按 Arena 课的纪律。报告应附对战次数矩阵，而不是只附排行。</p>',9)),(r(),s(n,null,{default:l(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%88%90%E5%AF%B9%E8%83%9C%E8%B4%9F%22%5D%20--%3E%20BT%5B%22Bradley-Terry%20%E4%BC%BC%E7%84%B6%22%5D%0A%20%20W%20--%3E%20ELO%5B%22%E5%9C%A8%E7%BA%BF%20Elo%22%5D%0A%20%20BT%20--%3E%20S%5B%22%E5%BC%BA%E5%BA%A6%20s%20%E4%B8%8E%E5%8C%BA%E9%97%B4%22%5D%0A%20%20ELO%20--%3E%20S%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("\\(s_i-s_j\\) 只在 logistic 链接下对应胜率。差 10 与差 100 的胜率含义不同，且依赖是否允许平局、是否有风格协变量。"),o("span",{class:"marginnote"},"代个数感受分差：Elo 差 100 对应期望胜率约 64%，差 200 约 76%，差 400 约 91%。所以「领先 15 Elo」的两模型其实接近五五开，样本稍一抖名次就能倒过来——把 15 分的差距写成新闻标题看着唬人，统计上什么都没说。"),e("不加协变量时，长度与格式被吸进 \\(s\\)，模型「变强」可能是变长。后课把风格当要控制的变量，而不是当强度。")],-1)),(r(),s(n,null,{default:l(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%A6%9C%E4%B8%8A%E5%88%86%E5%B7%AE%E5%A4%9A%E5%B0%91%E6%89%8D%E7%AE%97%E5%BC%BA%3F%22%5D%20--%3E%20D1%5B%22%E5%B7%AE%2010%20Elo%3A%20%E6%9C%9F%E6%9C%9B%E8%83%9C%E7%8E%87%E7%BA%A6%2051%25%22%5D%0A%20%20Q%20--%3E%20D2%5B%22%E5%B7%AE%20100%20Elo%3A%20%E7%BA%A6%2064%25%22%5D%0A%20%20Q%20--%3E%20D3%5B%22%E5%B7%AE%20200%20Elo%3A%20%E7%BA%A6%2076%25%22%5D%0A%20%20Q%20--%3E%20D4%5B%22%E5%B7%AE%20400%20Elo%3A%20%E7%BA%A6%2091%25%22%5D%0A%20%20D4%20--%3E%20NOTE%5B%22%E5%89%8D%E6%8F%90%3A%20logistic%20%E9%93%BE%E6%8E%A5%3Cbr%2F%3E%E4%B8%94%E6%9C%AA%E6%B7%B7%E5%85%A5%E9%A3%8E%E6%A0%BC%E7%BA%A2%E5%88%A9%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>BT 不处理多轴偏好（有人要短、有人要长）。混合人群下的单一 \\(s\\) 是投影。<span class="marginnote">初学者容易以为单一 \\(s\\) 能概括「谁更好」。实际上偏爱短回答与偏爱长回答的投票者混在一起、被压成一个分数后，\\(s\\) 高可能只说明模型的长回答风格碰巧占多数票。分数回答的是「谁更讨这批投票者喜欢」，不回答「谁更对」——这两件事在开放任务上经常不是一回事。</span>下一课风格控制把长度等可观测混淆从 \\(s\\) 里拆出去。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Elo / BT 是成对胜负的强度估计，必须报场次与区间。</li><li>流量偏与非传递性会破坏单一分数。</li><li>未控风格时，\\(s\\) 含长度等混淆。</li><li>出处：Bradley &amp; Terry；Elo；Chatbot Arena 实践。</li></ul>',4))])}const C=B(p,[["render",m]]);export{f as __pageData,C as default};
